function gd_client_portal_collab_table($suffix) { global $wpdb; return $wpdb->prefix . 'gd_' . $suffix; }
function gd_client_portal_activate_collaboration_tables() {
    global $wpdb; require_once ABSPATH . 'wp-admin/includes/upgrade.php'; $c=$wpdb->get_charset_collate();
    $tasks=gd_client_portal_collab_table('project_tasks');
    $updates=gd_client_portal_collab_table('project_updates');
    $notes=gd_client_portal_collab_table('project_internal_notes');
    dbDelta("CREATE TABLE {$tasks} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, project_id bigint(20) unsigned NOT NULL, tenant_id bigint(20) unsigned NOT NULL DEFAULT 0, title varchar(255) NOT NULL, description text NULL, status varchar(30) NOT NULL DEFAULT 'todo', priority varchar(20) NOT NULL DEFAULT 'normal', assigned_to bigint(20) unsigned NOT NULL DEFAULT 0, due_date datetime NULL, created_by bigint(20) unsigned NOT NULL DEFAULT 0, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at datetime NULL, PRIMARY KEY(id), KEY project_id(project_id), KEY tenant_id(tenant_id), KEY assigned_to(assigned_to), KEY status(status), KEY due_date(due_date) ) {$c};");
    dbDelta("CREATE TABLE {$updates} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, project_id bigint(20) unsigned NOT NULL, tenant_id bigint(20) unsigned NOT NULL DEFAULT 0, author_id bigint(20) unsigned NOT NULL DEFAULT 0, visibility varchar(20) NOT NULL DEFAULT 'client', title varchar(255) NOT NULL, body longtext NOT NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY project_id(project_id), KEY tenant_id(tenant_id), KEY author_id(author_id), KEY visibility(visibility), KEY created_at(created_at) ) {$c};");
    dbDelta("CREATE TABLE {$notes} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, project_id bigint(20) unsigned NOT NULL, tenant_id bigint(20) unsigned NOT NULL DEFAULT 0, author_id bigint(20) unsigned NOT NULL DEFAULT 0, body longtext NOT NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY project_id(project_id), KEY tenant_id(tenant_id), KEY author_id(author_id), KEY created_at(created_at) ) {$c};");
}
