function gd_client_portal_collab_is_manager() { return current_user_can('manage_options') || gd_client_portal_user_is_tenant_admin(); }
function gd_client_portal_collab_project($id) { $p=gd_client_portal_get_project_by_id(absint($id)); return ($p && gd_client_portal_verify_project_access($p)) ? $p : false; }
function gd_client_portal_collab_team($project) { return function_exists('gd_client_portal_get_project_assignments') ? gd_client_portal_get_project_assignments($project->id) : array(); }
function gd_client_portal_collab_statuses() { return array('todo'=>'To do','in_progress'=>'In progress','blocked'=>'Blocked','done'=>'Done'); }
function gd_client_portal_collab_priorities() { return array('low'=>'Low','normal'=>'Normal','high'=>'High','urgent'=>'Urgent'); }

function gd_client_portal_collab_get_tasks($project_id=0,$limit=100) {
    $tenant=0; if(!$project_id && !gd_client_portal_is_platform_admin()) $tenant=absint(gd_client_portal_get_current_tenant_id());
    if(!$project_id && !$tenant)return array();
    return gdcp_collaboration_service()->tasks(absint($project_id),$tenant,$limit);
}
function gd_client_portal_collab_get_updates($project_id=0,$limit=30,$include_internal=false) {
    $tenant=0; if(!$project_id && !gd_client_portal_is_platform_admin()) $tenant=absint(gd_client_portal_get_current_tenant_id());
    if(!$project_id && !$tenant)return array();
    return gdcp_collaboration_service()->updates(absint($project_id),$tenant,$limit,$include_internal);
}
function gd_client_portal_collab_get_notes($project_id) { return gdcp_collaboration_service()->notes(absint($project_id),100); }
function gd_client_portal_collab_notify_mentions($text,$project,$actor_id) {
    if(!function_exists('gd_client_portal_create_notification'))return;
    preg_match_all('/@([A-Za-z0-9._-]{2,60})/',(string)$text,$m); if(empty($m[1]))return;
    foreach(array_unique($m[1]) as $login){$u=get_user_by('login',$login);if(!$u||absint($u->ID)===absint($actor_id))continue;$tid=absint(get_user_meta($u->ID,'gd_client_portal_tenant_id',true));if($tid!==absint($project->tenant_id))continue;gd_client_portal_create_notification($u->ID,__('You were mentioned','gd-client-portal'),sprintf(__('You were mentioned in project “%s”.','gd-client-portal'),$project->title),'mention',$project->id,$project->tenant_id);}
}

function gd_client_portal_collab_task_ajax() {
    if(!is_user_logged_in()||!gd_client_portal_verify_request()||!gd_client_portal_collab_is_manager())wp_send_json_error(array('message'=>__('Permission denied.','gd-client-portal')),403);
    check_ajax_referer('gd_client_portal_collaboration','nonce'); global $wpdb;
    $action=sanitize_key(wp_unslash($_POST['operation']??''));$id=absint($_POST['task_id']??0);$project=gd_client_portal_collab_project($_POST['project_id']??0);
    if($action==='delete'){$task=gdcp_collaboration_service()->task($id);if(!$task||!gd_client_portal_collab_project($task->project_id))wp_send_json_error(array('message'=>'Task access denied.'),403);gdcp_collaboration_service()->delete_task($id);wp_send_json_success(array('message'=>'Task deleted.'));}
    if(!$project)wp_send_json_error(array('message'=>'Project access denied.'),403);
