    if(!isset($statuses[$status]))$status='todo';if(!isset($priorities[$priority]))$priority='normal';
    if($assignee){$u=gd_client_portal_cached_user($assignee);$ut=absint(get_user_meta($assignee,'gd_client_portal_tenant_id',true));if(!$u||$ut!==absint($project->tenant_id)||user_can($u,'manage_options'))$assignee=0;}
    if($action==='create'){if(!$title)wp_send_json_error(array('message'=>'Task title is required.')); $new=gdcp_collaboration_service()->create_task($project,array('title'=>$title,'description'=>$desc,'status'=>$status,'priority'=>$priority,'assigned_to'=>$assignee,'due_date'=>$due?$due.' 23:59:59':null,'created_by'=>gd_client_portal_cached_current_user_id(),'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')));if($assignee&&function_exists('gd_client_portal_create_notification'))gd_client_portal_create_notification($assignee,__('New project task','gd-client-portal'),sprintf(__('You were assigned “%s” on %s.','gd-client-portal'),$title,$project->title),'task',$project->id,$project->tenant_id);if(function_exists('gd_client_portal_audit_log'))gd_client_portal_audit_log('task_created',$title,$project->id,$project->tenant_id,$desc,'task',$new,array('assigned_to'=>$assignee));wp_send_json_success(array('message'=>'Task created.','id'=>$new));}
    if($action==='update'){$task=gdcp_collaboration_service()->task($id,$project->id);if(!$task)wp_send_json_error(array('message'=>'Task not found.'),404);$completed=$status==='done'?current_time('mysql'):null;gdcp_collaboration_service()->update_task($id,array('title'=>$title?:$task->title,'description'=>$desc,'status'=>$status,'priority'=>$priority,'assigned_to'=>$assignee,'due_date'=>$due?$due.' 23:59:59':null,'updated_at'=>current_time('mysql'),'completed_at'=>$completed));if($assignee&&$assignee!==(int)$task->assigned_to&&function_exists('gd_client_portal_create_notification'))gd_client_portal_create_notification($assignee,__('Task assigned','gd-client-portal'),sprintf(__('You were assigned “%s” on %s.','gd-client-portal'),$title?:$task->title,$project->title),'task',$project->id,$project->tenant_id);wp_send_json_success(array('message'=>'Task updated.'));}
    wp_send_json_error(array('message'=>'Unknown operation.'));
}
add_action('wp_ajax_gd_client_portal_collab_task','gd_client_portal_collab_task_ajax');

function gd_client_portal_collab_update_ajax() {
    if(!is_user_logged_in()||!gd_client_portal_verify_request())wp_send_json_error(array('message'=>'Access denied.'),403);check_ajax_referer('gd_client_portal_collaboration','nonce');$project=gd_client_portal_collab_project($_POST['project_id']??0);if(!$project)wp_send_json_error(array('message'=>'Project access denied.'),403);$title=sanitize_text_field(wp_unslash($_POST['title']??''));$body=sanitize_textarea_field(wp_unslash($_POST['body']??''));if(!$body)wp_send_json_error(array('message'=>'Update text is required.'));$new=gdcp_collaboration_service()->create_update($project,array('author_id'=>gd_client_portal_cached_current_user_id(),'visibility'=>'client','title'=>$title?:__('Project update','gd-client-portal'),'body'=>$body,'created_at'=>current_time('mysql')));gd_client_portal_collab_notify_mentions($body,$project,gd_client_portal_cached_current_user_id());if(function_exists('gd_client_portal_create_notification')){$owner=absint($project->user_id);if($owner&&$owner!==gd_client_portal_cached_current_user_id())gd_client_portal_create_notification($owner,__('New project update','gd-client-portal'),$title?:__('A new update was posted.','gd-client-portal'),'project_update',$project->id,$project->tenant_id);}if(function_exists('gd_client_portal_audit_log'))gd_client_portal_audit_log('project_update_posted',$title?:'Project update',$project->id,$project->tenant_id,$body,'project_update',$new);wp_send_json_success(array('message'=>'Update posted.'));
}
