function gd_client_portal_render_collaboration($atts=array()) {
    if(!gd_client_portal_verify_request())return gd_client_portal_render_access_gate(__('Team Workspace','gd-client-portal'),__('Please sign in to collaborate on projects.','gd-client-portal'));
    wp_enqueue_style('gd-client-portal-collaboration');wp_enqueue_style('gdcp-collaboration-approvals-ux');wp_enqueue_script('gd-client-portal-collaboration');$project_id=absint($_GET['collab_project']??$_GET['project_id']??0);$projects=gd_client_portal_get_visible_projects();$project=$project_id?gd_client_portal_collab_project($project_id):false;$nonce=wp_create_nonce('gd_client_portal_collaboration');
    ob_start();echo '<div class="gd-collab" data-nonce="'.esc_attr($nonce).'">';
    if(!$project){echo '<div class="gd-collab-hero"><div><span>CLIENT PORTAL · V3.6</span><h2>Collaboration Workspace</h2><p>Coordinate tasks, team assignments, project updates and client-visible progress in one place.</p></div></div><div class="gd-collab-projects">';foreach($projects as $p)echo '<a class="gd-collab-project" href="'.esc_url(add_query_arg('collab_project',$p->id,get_permalink())).'"><strong>'.esc_html($p->title).'</strong><span>'.esc_html(ucwords(str_replace('_',' ',$p->current_stage))).' · '.intval($p->progress).'%</span></a>';if(!$projects)echo '<div class="gd-collab-empty">No accessible projects.</div>';echo '</div></div>';return ob_get_clean();}
    $tasks=gd_client_portal_collab_get_tasks($project->id);$updates=gd_client_portal_collab_get_updates($project->id,30);$notes=gd_client_portal_collab_get_notes($project->id);$team=gd_client_portal_collab_team($project);$manager=gd_client_portal_collab_is_manager();$statuses=gd_client_portal_collab_statuses();$priorities=gd_client_portal_collab_priorities();
    echo '<div class="gd-collab-hero"><div><a href="'.esc_url(remove_query_arg('collab_project')).'">← All projects</a><span>PROJECT COLLABORATION</span><h2>'.esc_html($project->title).'</h2><p>Coordinate work, keep clients informed, and move the project toward review.</p></div><div class="gd-collab-progress"><strong>'.intval($project->progress).'%</strong><small>complete</small></div></div>';
    $task_total=count($tasks);$task_done=count(array_filter($tasks,function($t){return $t->status==='done';}));
    echo '<div class="gd-collab-workflow-summary"><div class="gd-collab-workflow-summary__item"><span class="gd-collab-workflow-summary__label">Current stage</span><span class="gd-collab-workflow-summary__value">'.esc_html(ucwords(str_replace('_',' ',$project->current_stage))).'</span></div><div class="gd-collab-workflow-summary__item"><span class="gd-collab-workflow-summary__label">Tasks completed</span><span class="gd-collab-workflow-summary__value">'.intval($task_done).' / '.intval($task_total).'</span></div><div class="gd-collab-workflow-summary__item"><span class="gd-collab-workflow-summary__label">Client updates</span><span class="gd-collab-workflow-summary__value">'.intval(count($updates)).'</span></div><div class="gd-collab-workflow-summary__item"><span class="gd-collab-workflow-summary__label">Next workflow focus</span><span class="gd-collab-workflow-summary__value">'.esc_html($project->current_stage==='approval'?'Client review':'Project delivery').'</span></div></div><div class="gd-collab-tabs"><button class="is-active" data-tab="board">Task board</button><button data-tab="updates">Updates</button><button data-tab="discussion">Discussion</button>'.($manager?'<button data-tab="internal">Internal notes</button>':'').'</div>';
    echo '<section class="gd-collab-panel is-active" data-panel="board"><div class="gd-collab-panel-head"><div><h3>Task board</h3><p>Assign work, set priorities and track delivery.</p></div>'.($manager?'<button class="gd-collab-primary" id="gd-collab-new-task">+ New task</button>':'').'</div><div id="gd-collab-task-form" class="gd-collab-form" hidden><div class="gd-collab-grid"><input id="gd-task-title" placeholder="Task title"><select id="gd-task-priority">'.implode('',array_map(function($k,$v){return '<option value="'.esc_attr($k).'">'.esc_html($v).' priority</option>';},array_keys($priorities),$priorities)).'</select><select id="gd-task-assignee"><option value="0">Unassigned</option>'.implode('',array_map(function($a){$u=gd_client_portal_cached_user($a->user_id);return '<option value="'.intval($a->user_id).'">'.esc_html($u?$u->display_name:'User #'.$a->user_id).'</option>';},$team)).'</select><input type="date" id="gd-task-due"></div><textarea id="gd-task-description" placeholder="Task details..."></textarea><button id="gd-task-save" class="gd-collab-primary">Create task</button><span id="gd-task-result"></span></div><div class="gd-collab-kanban">';foreach($statuses as $sk=>$sv){echo '<div class="gd-collab-column"><h4>'.esc_html($sv).'<span>'.count(array_filter($tasks,function($t)use($sk){return $t->status===$sk;})).'</span></h4>';foreach($tasks as $t){if($t->status!==$sk)continue;$u=$t->assigned_to?gd_client_portal_cached_user($t->assigned_to):false;echo '<article class="gd-task-card"><div><span class="gd-task-priority priority-'.esc_attr($t->priority).'">'.esc_html(ucfirst($t->priority)).'</span>'.($t->due_date?'<time>'.esc_html(wp_date(get_option('date_format'),strtotime($t->due_date))).'</time>':'').'</div><strong>'.esc_html($t->title).'</strong><p>'.esc_html(wp_trim_words($t->description,18)).'</p><small>'.esc_html($u?$u->display_name:'Unassigned').'</small>';if($manager)echo '<div class="gd-task-actions"><button data-task-action="edit" data-task-id="'.intval($t->id).'">Edit</button><button data-task-action="done" data-task-id="'.intval($t->id).'">'.($t->status==='done'?'Reopen':'Done').'</button></div>';echo '</article>';}echo '</div>';};echo '</div></section>';
    echo '<section class="gd-collab-panel" data-panel="updates"><div class="gd-collab-panel-head"><div><h3>Client-visible updates</h3><p>Keep the client informed without exposing internal notes.</p></div></div>'.($manager?'<div class="gd-collab-form"><input id="gd-update-title" placeholder="Update title"><textarea id="gd-update-body" placeholder="Share a project update… Use @username to mention a team member."></textarea><button id="gd-update-save" class="gd-collab-primary">Post update</button><span id="gd-update-result"></span></div>':'');echo '<div class="gd-collab-feed">';foreach($updates as $u){$a=gd_client_portal_cached_user($u->author_id);echo '<article><div class="gd-feed-meta"><strong>'.esc_html($a?$a->display_name:'Portal user').'</strong><time>'.esc_html(wp_date(get_option('date_format').' '.get_option('time_format'),strtotime($u->created_at))).'</time></div><h4>'.esc_html($u->title).'</h4><p>'.nl2br(esc_html($u->body)).'</p></article>';}if(!$updates)echo '<div class="gd-collab-empty">No project updates yet.</div>';echo '</div></section>';
    echo '<section class="gd-collab-panel" data-panel="discussion"><div class="gd-collab-panel-head"><div><h3>Project discussion</h3><p>Continue the existing secure project conversation below.</p></div></div>';if(function_exists('gd_client_portal_render_project_workspace'))echo '<div class="gd-collab-message-note">Use the Project Workspace message composer to send full conversation messages and attachments.</div><a class="gd-collab-primary inline" href="'.esc_url(add_query_arg('project_id',$project->id,get_permalink())).'">Open project conversation →</a>';echo '</section>';
    if($manager){echo '<section class="gd-collab-panel" data-panel="internal"><div class="gd-collab-panel-head"><div><h3>Internal notes</h3><p>Private notes visible only to authorized project managers.</p></div></div><div class="gd-collab-form"><textarea id="gd-note-body" placeholder="Private team note…"></textarea><button id="gd-note-save" class="gd-collab-primary">Save internal note</button><span id="gd-note-result"></span></div><div class="gd-collab-feed internal">';foreach($notes as $n){$a=gd_client_portal_cached_user($n->author_id);echo '<article><div class="gd-feed-meta"><strong>'.esc_html($a?$a->display_name:'Portal user').'</strong><time>'.esc_html($n->created_at).'</time></div><p>'.nl2br(esc_html($n->body)).'</p></article>';}if(!$notes)echo '<div class="gd-collab-empty">No internal notes.</div>';echo '</div></section>';}
    echo '</div>';return ob_get_clean();
}
