function gd_client_portal_collaboration_admin(){if(!gd_client_portal_user_can_access_admin())wp_die('Access denied.');$projects=gd_client_portal_get_visible_projects();echo '<div class="wrap gd-collab-admin"><h1>Collaboration Workspace</h1><p>Open a project to manage tasks, updates and internal collaboration.</p><table class="widefat striped"><thead><tr><th>Project</th><th>Stage</th><th>Progress</th><th>Tasks</th><th>Team lead</th><th>Open</th></tr></thead><tbody>';foreach($projects as $p){$tasks=gd_client_portal_collab_get_tasks($p->id);$lead=function_exists('gd_client_portal_get_project_lead')?gd_client_portal_get_project_lead($p->id):false;$u=$lead?gd_client_portal_cached_user($lead->user_id):false;echo '<tr><td><strong>'.esc_html($p->title).'</strong><br>#'.intval($p->id).'</td><td>'.esc_html(ucwords(str_replace('_',' ',$p->current_stage))).'</td><td>'.intval($p->progress).'%</td><td>'.intval(count($tasks)).'</td><td>'.esc_html($u?$u->display_name:'Unassigned').'</td><td><a class="button button-primary" href="'.esc_url(add_query_arg('collab_project',$p->id,gd_client_portal_get_dashboard_url())).'">Open workspace</a></td></tr>';}if(!$projects)echo '<tr><td colspan="6">No projects found.</td></tr>';echo '</tbody></table></div>';}
